import re
from dataclasses import dataclass

NAME_PATTERN = re.compile(r"name:\s*'([^']*)'")
PARAMS_PATTERN = re.compile(r"params:\s*'([^']*)'")
METRIC_PATTERNS = {
    "blimp": re.compile(r"blimp:\s*(null|[-0-9.eE+]+)"),
    "arc": re.compile(r"arc:\s*(null|[-0-9.eE+]+)"),
    "wiki": re.compile(r"wiki:\s*(null|[-0-9.eE+]+)"),
}
MODELS_ARRAY_PATTERN = re.compile(r"const\s+models\s*=\s*\[")


@dataclass(frozen=True)
class LeaderboardEntry:
    name: str
    params: float
    blimp: float | None
    arc: float | None
    wiki: float | None


def parse_params_text(text: str) -> float:
    cleaned = text.strip().upper().replace(",", "")
    if not cleaned:
        raise ValueError(f"expected a parameter count like '1M', got {text!r}")
    multipliers = {"B": 1e9, "M": 1e6, "K": 1e3}
    suffix = cleaned[-1]
    if suffix in multipliers:
        return float(cleaned[:-1]) * multipliers[suffix]
    return float(cleaned)


def extract_models_block(html: str) -> str:
    match = MODELS_ARRAY_PATTERN.search(html)
    if match is None:
        raise ValueError("expected 'const models = [' in leaderboard html, not found")
    depth = 0
    for index in range(match.end() - 1, len(html)):
        char = html[index]
        if char == "[":
            depth += 1
        elif char == "]":
            depth -= 1
            if depth == 0:
                return html[match.end() : index]
    raise ValueError("unterminated models array in leaderboard html")


def split_entry_blocks(models_block: str) -> list[str]:
    blocks: list[str] = []
    depth = 0
    start = -1
    for index, char in enumerate(models_block):
        if char == "{":
            if depth == 0:
                start = index
            depth += 1
        elif char == "}":
            depth -= 1
            if depth == 0 and start >= 0:
                blocks.append(models_block[start : index + 1])
    return blocks


def parse_metric(block: str, key: str) -> float | None:
    match = METRIC_PATTERNS[key].search(block)
    if match is None or match.group(1) == "null":
        return None
    return float(match.group(1))


def parse_entry_block(block: str) -> LeaderboardEntry | None:
    name_match = NAME_PATTERN.search(block)
    params_match = PARAMS_PATTERN.search(block)
    if name_match is None or params_match is None:
        return None
    return LeaderboardEntry(
        name=name_match.group(1),
        params=parse_params_text(params_match.group(1)),
        blimp=parse_metric(block, "blimp"),
        arc=parse_metric(block, "arc"),
        wiki=parse_metric(block, "wiki"),
    )


def parse_leaderboard_html(html: str) -> list[LeaderboardEntry]:
    blocks = split_entry_blocks(extract_models_block(html))
    entries = [entry for entry in map(parse_entry_block, blocks) if entry is not None]
    if not entries:
        raise ValueError("leaderboard html parsed to zero model entries")
    return entries
